def process_inline_code(text):
    """Convert `code` to <code>code</code>"""
    result = text
    i = 0
    while i < len(result) - 1:
        if result[i] == '`' and i + 1 < len(result):
            # Find the closing `
            j = i + 1
            while j < len(result) and result[j] != '`':
                j += 1
            if j < len(result) and result[j] == '`':
                # Replace `code` with <code>code</code>
                code_text = result[i+1:j]
                # Escape HTML characters in code text
                escaped_code = code_text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
                result = result[:i] + f"<code>{escaped_code}</code>" + result[j+1:]
                i += len(f"<code>{escaped_code}</code>")
            else:
                # No closing ` found, keep as is
                i += 1
        else:
            i += 1

    return result

